import hashlib,json
from pathlib import Path
r=Path(__file__).resolve().parents[2]; audit=r/'Examtopics/audit'
s=(r/'CCNA-App/app/src/main/assets/data/ccna_cards_data.js').read_text(encoding='utf-8'); qs=json.loads(s[s.index('['):].strip().rstrip(';')); by={q['id']:q for q in qs}
fp=lambda q:hashlib.sha256(json.dumps(q,ensure_ascii=False,sort_keys=True,separators=(',',':')).encode()).hexdigest()
route='https://www.cisco.com/c/en/us/support/docs/ip/enhanced-interior-gateway-routing-protocol-eigrp/8651-21.html'
mdix='https://www.cisco.com/c/en/us/td/docs/switches/lan/catalyst9300/software/release/17-17/command_reference/b_1717_9300_cr/interface_and_hardware_commands.html'
wifi='https://www.cisco.com/c/en/us/support/docs/wireless/catalyst-9800-series-wireless-controllers/223061-migrate-to-wi-fi-7-and-6ghz.html'
notes={
951:('CCMP可同时保证完整性，原A亦可成立；更换干扰项并修正6 GHz对TKIP的错误断言。',{'options':[{'label':'A','text':'compresses all wireless data to reduce airtime'},{'label':'B','text':'uses 802.1X as the standard encoding method'},{'label':'C','text':'uses protocols such as TKIP and CCMP to secure data'},{'label':'D','text':'only works with the 5 GHz frequency'}], 'explanation':'C。TKIP 和 CCMP 是不同年代的无线数据保护协议：TKIP 属旧式 WPA 机制，CCMP 使用 AES 并提供机密性及完整性保护。802.1X 是端口访问控制/认证框架而非数据加密方法；数据压缩不是加密的定义，无线安全也不局限于 5 GHz。不要由此推断 TKIP 可用于 6 GHz：新频段有更严格的安全要求，应使用兼容的现代配置。'},wifi),
952:('已查看拓扑，补相同STP实例和连通条件，修正 Bridge 拼写。',{'prompt':'Refer to the exhibit. For one common STP instance, assume all shown switches can exchange BPDUs and each has the listed bridge priority and MAC address. Which switch becomes the root bridge?', 'options':[{'label':o['label'],'text':o['text'].replace('Bndge','Bridge')} for o in by[952]['options']], 'explanation':'D。相同实例内先比较桥 ID 的优先级（含相同的扩展系统 ID）：SW3 和 SW4 的 53248 低于 SW1 和 SW2 的 61440；再比较 MAC，`00:10:a1:22:11:63` 小于 `00:10:a1:35:d9:86`，因此 SW4 当选。若实例不同或 BPDU 不能互通，不能直接推断整个拓扑只有同一个根桥。'},'https://www.cisco.com/c/en/us/support/docs/lan-switching/spanning-tree-protocol/10556-16.html'),
953:('已查看路由和拓扑；限定已安装可用路由，说明图中直连接口地址和前缀存在不一致。',{'prompt':'Refer to the exhibit. Assuming the displayed static routes are installed and their next hops reachable, PC A sends to 10.225.34.225. Which router is the next hop selected by router Y?', 'explanation':'C。目的地址落在 `10.224.0.0/15`（范围 10.224.0.0–10.225.255.255）内，也匹配更短的 /11、/9 和 /8；其中 /15 最长，其下一跳为 `10.224.1.4`，图上对应 Router C。路由选择安装与转发匹配是不同阶段；题目假定静态路由和下一跳均已可用。图中 Y 的 G0/0 地址 10.224.1.1 与显示的直连 `10.224.0.0/24` 不一致，真实部署需先修正地址或前缀。'},route),
954:('图中10.18.75.113/27不是网络前缀，RIP 16不可达；改为候选路由并说明规范网络。',{'prompt':'Refer to the exhibit as a list of candidate routes, not a literal routing table. All candidates refer to destination 10.18.75.113 in network 10.18.75.96/27. Assuming default administrative distances, reachable next hops and no other routes, which interface is selected?', 'explanation':'A。相同的 `10.18.75.96/27` 前缀先比较路由来源的管理距离：默认 OSPF 110 优于 RIP 120。两条 OSPF 候选的 cost 分别为 6906（G0/6）和 23018（G0/3），因此选 G0/6。图中的 `10.18.75.113/27` 是该网段内的主机地址，不是规范的 /27 网络号；RIP 跳数 16 还表示不可达，不能当作有效可用候选。选路装表与装表后最长匹配是不同阶段。'},route),
955:('修正FTP主动/被动数据端口的绝对化和TFTP块大小扩展。',{'explanation':'A。FTP 控制和数据使用独立的 TCP 连接：控制通常连接服务端 21 端口，文件或目录数据使用另建的数据连接。主动模式一般由服务端发起数据连接，被动模式由客户端连接服务端协商端口；实际端口不应一律断言为 20。B 的块号与确认属于 TFTP 的常见机制；TFTP 基本块长是 512 字节但可以协商扩展。C 错在“总是”：FTP 可要求用户名和密码，也可配置匿名访问。D 的 UDP 69 是 TFTP 的初始请求端口，而非 FTP 控制端口。'},'https://www.rfc-editor.org/rfc/rfc959'),
956:('图中notconnect不能证明根因为错误线缆；改问可能性并限定两端无Auto-MDIX。',{'prompt':'Refer to the exhibit. The interfaces at both ends do not support auto-MDIX. Which of the following is a possible physical-layer cause of the displayed status?', 'explanation':'B。图中 Fa0/1 为 `down/down`、`notconnect`，表明链路没有建立。错误的双绞线类型在双方均无 auto-MDIX 时可能造成这一现象；线缆未插、损坏、对端断电等也可能造成相同状态，仅凭图不能唯一确定根因。A 的 shutdown 通常显示 administratively down；STP 阻塞通常不使物理链路 down；端口安全的 shutdown 违规通常表现为 err-disabled，而非该图的 notconnect。应检查两端电源、线缆、接口与 MDIX 配置。'},mdix),
957:('修正泛洪不回入端口、STP和VLAN许可边界；用帧而非包。',{'prompt':'PC1 sends a unicast Ethernet frame toward PC2, but PC2’s destination MAC address is absent from the switch MAC address table. The switch forwards the frame to eligible ports in the same VLAN except the ingress port. Which switching concept does this describe?', 'explanation':'A。这是未知单播帧泛洪：交换机在对应 VLAN 查不到目的 MAC 时，通常复制帧到该 VLAN 内除入端口外的符合条件的转发端口；STP 状态、VLAN 许可及其他限制可能排除端口。交换机从收到帧的源 MAC 学习位置，若 PC2 回帧且学习成功，后续帧可按表项单播。MAC 地址表是查找数据结构，STP 控制环路，老化删除过期动态表项，均不是题述动作。'},'https://www.cisco.com/c/en/us/support/docs/lan-switching/catalyst-6500-series-switches/23563-143.html'),
958:('核对原图R1的MAC与LAN前缀，保留答案并补DAD及文档前缀条件。',{'explanation':'D。图中 Boston R1 的 LAN 前缀为 `2001:db8:3bb8:3bb1::/64`，E0/1 的 MAC 为 `ca:01:b3:b8:00:01`。中间插入 `ff:fe` 得 `ca:01:b3:ff:fe:b8:00:01`，首字节与 0x02 异或得到 `c8`，接口标识为 `c801:b3ff:feb8:0001`，拼接得 `2001:db8:3bb8:3bb1:c801:b3ff:feb8:1`。A/B 的接口标识有误，C 前缀不符。地址要成功使用仍需接口配置和重复地址检测等条件；`2001:db8::/32` 是文档示例地址。'},'https://www.rfc-editor.org/rfc/rfc4291'),
959:('纠正trunk native VLAN可不标记、隔离并非自动防火墙。',{'explanation':'D。支持 VLAN 的二层交换机可把端口分入不同广播域，支持 802.1Q 的 trunk 可通过标签区分链路上的多个 VLAN；具体实现中 native VLAN 流量可能不带标签。VLAN 之间要互通通常需要三层转发，VLAN 本身并不等同完整安全策略。A 错在所有帧都发送所有设备，已知单播通常按 MAC 表转发；B 的单一共享冲突域更像集线器；C 错在只支持半双工，交换端口也可工作于全双工。'},'https://www.cisco.com/c/en/us/td/docs/switches/lan/c9000/lyr2-fwd/vlan/vlan-configuration-guide/configure-vlan-trunks.html'),
960:('限定传统10/100BASE-TX引脚条件，消除同类设备一律交叉的泛化。',{'prompt':'Two Ethernet interfaces use the same 10/100BASE-TX MDI pinout and auto-MDIX is unavailable. The link requires pin 1 to pin 3 and pin 2 to pin 6. Which cable type provides this mapping?', 'explanation':'C。交叉线将一端的 1、2 接到另一端的 3、6，且反向交叉另一对，使传统 10/100BASE-TX 同类引脚接口的发送对连接对端接收对。A 直通线保持同号引脚相连；B 和 D 是用于控制台的线缆类型而非此以太网交叉连接。设备类别是简化经验，实际应以接口引脚、以太网标准及 auto-MDIX 支持为准。'},mdix),
}
cor=[]; report=['# Q951–Q960 逐题审查','', '逐题检查题干、全部选项、答案、解析及图片/CLI；下列问题均已制作可应用修订。图像按原题数据提取并直接查看。','']
for n,(reason,updates,url) in notes.items():
 q=by[n]; c=dict(id=n,original_qid=q['qid'],before_sha256=fp(q),reason=reason,updates=updates,review=dict(prompt='checked',options='checked',answer='checked and retained',explanation='checked and corrected',image='viewed' if q.get('image') else 'none required',code_cli='checked',finding=reason,reference=url))
 if q.get('image'):
  p=audit/'exhibits'/f'q{n}_agent.jpg';c['exhibit_path']=str(p.relative_to(audit)).replace('\\','/');c['image_sha256']=hashlib.sha256(p.read_bytes()).hexdigest()
 cor.append(c);report.append(f'- Q{n}（{q["qid"]}）：{reason} 答案 {",".join(q["answer"])} 保留。依据：{url}')
out=dict(scope='Q951–Q960',preserve_question_ids=True,corrections=cor,limitations='人工审查题目和展图；未进行设备实测。')
(audit/'agent-0951-0960.json').write_text(json.dumps(out,ensure_ascii=False,indent=2)+'\n',encoding='utf-8'); (audit/'agent-0951-0960.md').write_text('\n'.join(report)+'\n',encoding='utf-8')
